// TestWork checks that the automation turns a todo-list row into the
// command.
func TestWork(t *testing.T) {
	item := cartstopublish.Row{CartID: uuid.MustParse("00000000-0000-4000-8000-000000000001")}

	var got []publishcart.PublishCart
	handler := func(_ context.Context, cmd publishcart.PublishCart) (eventsourcing.AppendResult, error) {
		got = append(got, cmd)
		return eventsourcing.AppendResult{}, nil
	}
	def := NewAutomation(cartstopublish.NewCartsToPublish(), nil, handler)
	if err := def.Work(t.Context(), item); err != nil {
		t.Fatalf("Work: %v", err)
	}

	want := []publishcart.PublishCart{{CartID: uuid.MustParse("00000000-0000-4000-8000-000000000001")}}
	gotJSON, _ := json.Marshal(got)
	wantJSON, _ := json.Marshal(want)
	if !bytes.Equal(gotJSON, wantJSON) {
		t.Errorf("Work sent %s, want %s", gotJSON, wantJSON)
	}
}
